              <p className="text-xs text-green-600 mt-0.5">{upiScreen.farmerVillage}</p>
              <p className="text-4xl font-black text-green-900 mt-3">₹{upiScreen.amount}</p>
              <p className="text-sm text-green-700 mt-1">Total amount to pay</p>
